sections.body:
保存为 asset-search.mjs，运行 node asset-search.mjs，无额外依赖。五份资产都属于 demo/sprite；A 未批准，B 超尺寸，C/D/E 满足本次条件。代码计算非零向量的余弦相似度，同分按 ID 排序，输入数组保持不变。

```js
/**
 * @file Compare filtered and unfiltered top-k asset retrieval.
 * @author liliwei
 * @date 2026-11-26
 * @LastEditors liliwei
 * @LastEditTime 2026-11-26
 */
/** @param {number[]} v Nonzero finite vector. @returns {number[]} Unit vector. */
export function unit(v) {
  if (!Array.isArray(v) || !v.length ||
      Array.from(v).some(x => !Number.isFinite(x))) throw Error('Invalid vector');
  const n = Math.hypot(...v);
  if (!Number.isFinite(n) || n === 0) throw Error('Invalid norm');
  return v.map(x => x / n);
}
/** @param {object} a Reviewed metadata. @returns {boolean} Eligibility for this brief only. */
export function eligible(a) {
  return a.project === 'demo' && a.kind === 'sprite' && a.approved === true &&
    [a.width, a.height].every(n => Number.isSafeInteger(n) && n > 0 && n <= 512);
}
/** @param {object[]} rows Same-model assets. @param {number[]} query Same-model query.
 * @param {number} k Maximum result count. @returns {object[]} Exact cosine ranking. */
export function rank(rows, query, k) {
  if (!Array.isArray(rows) || !Number.isSafeInteger(k) || k < 1) throw Error('Invalid input');
  const q = unit(query), ids = new Set();
  return rows.map(a => {
    if (!a || typeof a.id !== 'string' || !a.id || ids.has(a.id)) throw Error('Invalid ID');
    ids.add(a.id);
    const v = unit(a.vector);
    if (v.length !== q.length) throw Error('Dimension mismatch');
    const score = v.reduce((s, x, i) => s + x * q[i], 0);
    return { ...a, score };
  }).sort((a, b) => b.score - a.score || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
    .slice(0, k);
}
export const assets = [
  { id: 'A', approved: null, width: 256, vector: [1, 0] },
  { id: 'B', approved: true, width: 2048, vector: [0.99, 0.1] },
  { id: 'C', approved: true, width: 256, vector: [0.9, 0.3] },
  { id: 'D', approved: true, width: 256, vector: [0.8, 0.6] },
  { id: 'E', approved: true, width: 256, vector: [0.6, 0.8] }
].map(a => ({ project: 'demo', kind: 'sprite', height: a.width, ...a }));
const query = [1, 0], k = 3;
console.log(JSON.stringify({
  lateFilter: rank(assets, query, k).filter(eligible).map(a => a.id),
  earlyFilter: rank(assets.filter(eligible), query, k).map(a => a.id)
}));
```

示例只检查已给出的元数据。approved 是审核结果的简写，不是许可证明；正式记录需要审批版本和证据链接。代码也无法识别混用了两个模型，只会拒绝维数不匹配等数值错误；导入层还应检查 modelId、revision、预处理与索引版本，拒绝混库。
